#include <iostream>
#include <string>
using namespace std;

int more(int n) {
    return n * 2;
}

string more(string s) {
    return s + s;
}

int main() {
    int n = 0;
    string w;
    cin >> n >> w;

    cout << more(n) << endl;
    cout << more(w) << endl;
    return 0;
}
